return {rw01={id="rw01",baseId="rwnpc01",combatid={2,100021},name="王庚金",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL王庚金：先到镖局问一问管事吧。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：好歹是知道了点方向，走吧少侠，得去码头和客栈一趟。先一同去码头找找当天当值的漕工吧。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL王庚金：货物的来源倒是确定了，接下来就是要去查一查是谁下的委托了。一起去客栈吧，希望能有些收获。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL王庚金：不能就这样走了......我去闹大点动静，吸引客栈人员的注意，客栈的货物多是放在后院中，得拜托少侠你调查一下了。NOR"}},{type="gaintab",args={"318001",5}},{type="objectmove",args={"rw01","hdroom0508"}},{type="outobject",args={"rw08"}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}},{type="doc",args={"CYN话音刚落，王庚金向你使了个眼色，开始在客栈门口嚷嚷着店大欺客，客栈卖假货之类的话。周掌柜赶忙过去，周围的食客也站起身来向外望去。NOR"}},{type="gaintab",args={"318001",6}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL王庚金：果然如此，客栈与官府官商勾结，背后只怕还有人在。不过知道了客栈囤了不少粮食，至少有办法解镇中的燃眉之急。NOR"}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"YEL王庚金：没想到赵叔竟然会如此，让少侠看了笑话了。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：我再去问问镖局中的其他人，明日我们一同再去一趟客栈，总有办法的。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="gaintab",args={"318001",9}},{type="delayer",args={3,"少侠稍安勿躁！"}},{type="outgame",args={"hdfb1803"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"318007",0}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318001",4}}}},autoResult2={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition3={relation="and"